//go:build windows

package external

import (
	"path/filepath"

	"golang.org/x/sys/windows"
)

// путьДляTor приводит путь к форме, которую tor под Windows точно
// переживёт: к короткому имени 8.3.
//
// Причина выяснена на живом tor 0.4.9.11. Он открывает файлы через
// однобайтовую кодировку, а не UTF-16: путь с кириллицей превращается в
// кракозябру, и tor отказывается стартовать — «Error creating directory
// ...: No such file or directory». У пользователя с русским именем
// учётной записи это происходило бы всегда. Короткое имя заодно убирает
// пробелы, из-за которых пришлось бы кавычить путь и экранировать слэши.
//
// Если короткого имени нет (файловая система его не хранит), возвращаем
// исходный путь: пусть лучше tor пожалуется сам, чем мы молча подставим
// то, чего нет.
func путьДляTor(путь string) string {
	абсолютный, err := filepath.Abs(путь)
	if err != nil {
		абсолютный = путь
	}

	широкий, err := windows.UTF16PtrFromString(абсолютный)
	if err != nil {
		return абсолютный
	}
	длина, err := windows.GetShortPathName(широкий, nil, 0)
	if err != nil || длина == 0 {
		return абсолютный
	}
	буфер := make([]uint16, длина)
	if _, err := windows.GetShortPathName(широкий, &буфер[0], длина); err != nil {
		return абсолютный
	}
	короткий := windows.UTF16ToString(буфер)
	if короткий == "" {
		return абсолютный
	}
	return короткий
}
